-- 0122 — THE ADULT DAY CARE PROGRAM, AS HUB DATA.
--
-- Dayan, 2026-09-21: "what I care the most about is the kitchen learning how to do this with
-- direct hub help and training."
--
-- The printed Operations Manual and Exhibit A menu are the same content as these rows: both are
-- generated from one source. A recipe card on the cook's phone and the binder in the kitchen
-- therefore cannot disagree about a portion or a temperature, which is the only way a compliance
-- menu survives contact with a real kitchen.
--
-- Everything here is DATA, not a new subsystem: recipes ride the existing recipes table, the cycle
-- is a table the kitchen screen reads, and the service log is what a delivery slip is printed from.
-- Additive only. Apply: wrangler d1 execute anejo --remote --file=migrations/0122_program_service.sql

-- Bilingual recipe fields. The cook reads Spanish; the facility's file is in English.
ALTER TABLE recipes ADD COLUMN name_es TEXT;
ALTER TABLE recipes ADD COLUMN summary_es TEXT;
ALTER TABLE recipes ADD COLUMN ingredients_es TEXT;
ALTER TABLE recipes ADD COLUMN steps_es TEXT;
ALTER TABLE recipes ADD COLUMN portion TEXT;          -- the approved portion, verbatim from the menu
ALTER TABLE recipes ADD COLUMN portion_es TEXT;
ALTER TABLE recipes ADD COLUMN program_key TEXT;      -- stable key the cycle points at

CREATE TABLE IF NOT EXISTS program_cycles (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  weeks       INTEGER NOT NULL DEFAULT 4,
  -- The dietitian's signature is what makes a menu servable under Rule 59A-16.105. It lives with
  -- the cycle, because a cycle without it is a proposal, not a menu.
  dietitian_name        TEXT,
  dietitian_credentials TEXT,
  dietitian_license     TEXT,
  reviewed_at           INTEGER,
  valid_through         INTEGER,
  active      INTEGER NOT NULL DEFAULT 1,
  notes       TEXT,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS program_cycle_items (
  id          TEXT PRIMARY KEY,
  cycle_id    TEXT NOT NULL REFERENCES program_cycles(id),
  week        INTEGER NOT NULL,            -- 1..weeks
  dow         INTEGER NOT NULL,            -- 1=Mon .. 5=Fri
  meal        TEXT NOT NULL,               -- breakfast|lunch|snack
  dish        TEXT NOT NULL,
  recipe_id   TEXT REFERENCES recipes(id), -- NULL for snacks, which are assembly only
  components  TEXT,                        -- JSON [{c:'P',text:'...'}] exactly as approved
  allergens   TEXT,
  created_at  INTEGER NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_cycle_slot ON program_cycle_items(cycle_id, week, dow, meal);

-- What actually happened, per site per meal. This is the delivery slip the Elder Affairs program
-- requires: menu, portions, counts, temperatures and both signatures.
CREATE TABLE IF NOT EXISTS program_service_log (
  id             TEXT PRIMARY KEY,
  site_id        TEXT,
  service_date   TEXT NOT NULL,            -- YYYY-MM-DD
  meal           TEXT NOT NULL,
  cycle_week     INTEGER,
  dish           TEXT,
  count_ordered  INTEGER,
  count_delivered INTEGER,
  temp_pack_f    REAL,
  temp_delivery_f REAL,
  substitution   TEXT,                     -- what was served instead, and why
  packed_by      TEXT,
  delivered_by   TEXT,
  received_by    TEXT,                     -- the facility staff member who signed
  notes          TEXT,
  created_at     INTEGER NOT NULL,
  updated_at     INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_pslog_date ON program_service_log(service_date, site_id);

-- Which cycle a contract site eats, and on what cadence.
ALTER TABLE contract_sites ADD COLUMN program_cycle_id TEXT;
ALTER TABLE contract_sites ADD COLUMN program_started_on TEXT;   -- YYYY-MM-DD, week 1 anchor

-- ---------------------------------------------------------------- recipes
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_sofrito', 'Sofrito (the base of almost every lunch)', 'Makes the menu taste like home cooking without salt. Cook once for the week.', '[{"item": "Vegetable oil", "qty": "1½ cups"}, {"item": "Yellow onion, small dice", "qty": "4 lb"}, {"item": "Green bell pepper, small dice", "qty": "3 lb"}, {"item": "Garlic, minced", "qty": "1 cup"}, {"item": "Ground cumin", "qty": "3 tbsp"}, {"item": "Dried oregano", "qty": "3 tbsp"}, {"item": "Bay leaves", "qty": "8"}, {"item": "Tomato sauce, no salt added", "qty": "2 qt"}, {"item": "Black pepper", "qty": "2 tbsp"}]', '["Heat oil in a rondeau over medium. Add onion and pepper; cook 8 to 10 minutes until soft, not browned.", "Add garlic, cumin, oregano, bay and pepper; cook 1 minute until fragrant.", "Add tomato sauce. Simmer 10 minutes. No salt is added: seasoning comes from the aromatics.", "Use hot, or cool per the cooling rule and refrigerate up to 4 days. Freeze in 1 qt portions up to 1 month."]', '["adult_day_care", "base", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Sofrito (la base de casi todos los almuerzos)', 'Le da sabor de casa al menú sin sal. Se hace una vez para toda la semana.', '[{"item": "Aceite vegetal", "qty": "1½ tazas"}, {"item": "Cebolla amarilla en cubitos", "qty": "4 lb"}, {"item": "Ají verde en cubitos", "qty": "3 lb"}, {"item": "Ajo picado", "qty": "1 taza"}, {"item": "Comino molido", "qty": "3 cdas"}, {"item": "Orégano seco", "qty": "3 cdas"}, {"item": "Hojas de laurel", "qty": "8"}, {"item": "Salsa de tomate sin sal", "qty": "2 cuartos de galón"}, {"item": "Pimienta negra", "qty": "2 cdas"}]', '["Caliente el aceite en una olla ancha a fuego medio. Agregue la cebolla y el ají; cocine de 8 a 10 minutos hasta que estén blandos, sin dorar.", "Agregue el ajo, el comino, el orégano, el laurel y la pimienta; cocine 1 minuto hasta que suelte el aroma.", "Agregue la salsa de tomate. Hierva a fuego lento 10 minutos. No se agrega sal: el sabor viene de los aromáticos.", "Use caliente, o enfríe según la regla de enfriamiento y refrigere hasta 4 días. Congele en porciones de 1 cuarto hasta 1 mes."]', '3 qt (use 1 cup per 10 portions of stew)', '3 galones (1 taza por cada 10 porciones de guiso)', 'sofrito');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_white_rice_enriched', 'White rice, enriched (1 cup cooked per lunch portion)', 'Enriched white rice is the grain participants expect. Brown rice is used where the menu says so.', '[{"item": "Long grain white rice, enriched", "qty": "7 lb (about 16 cups dry)"}, {"item": "Water", "qty": "4 gal"}, {"item": "Vegetable oil", "qty": "½ cup"}, {"item": "Salt", "qty": "none added"}]', '["Rinse rice once. Combine with water and oil in a steam pan or rice cooker.", "Cook covered until water is absorbed and grains are tender, about 20 minutes.", "Fluff, hold at 135°F or above, or cool per the cooling rule."]', '["adult_day_care", "base", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Arroz blanco enriquecido (1 taza cocida por almuerzo)', 'El arroz blanco enriquecido es el que los participantes esperan. El arroz integral se usa solo donde el menú lo indica.', '[{"item": "Arroz blanco de grano largo, enriquecido", "qty": "7 lb (unas 16 tazas crudas)"}, {"item": "Agua", "qty": "4 galones"}, {"item": "Aceite vegetal", "qty": "½ taza"}, {"item": "Sal", "qty": "no se agrega"}]', '["Enjuague el arroz una vez. Combine con el agua y el aceite en bandeja de vapor u olla arrocera.", "Cocine tapado hasta que absorba el agua y el grano esté tierno, unos 20 minutos.", "Suelte con tenedor, mantenga a 135°F o más, o enfríe según la regla de enfriamiento."]', '45 cups cooked', '45 tazas cocidas', 'white_rice_enriched');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_congr', 'Congrí (rice and black beans)', 'Counts as the grain. The beans in it do not replace the vegetable component.', '[{"item": "Long grain white rice, enriched", "qty": "6 lb"}, {"item": "Black beans, cooked, with liquid", "qty": "2 qt"}, {"item": "Sofrito", "qty": "3 cups"}, {"item": "Water or unsalted bean liquid", "qty": "3½ gal"}, {"item": "Bay leaf", "qty": "4"}]', '["Combine sofrito, beans and liquid; bring to a simmer.", "Stir in rice, cover and cook until tender, about 25 minutes.", "Rest 5 minutes, fluff, hold at 135°F or above."]', '["adult_day_care", "base", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Congrí (arroz con frijoles negros)', 'Cuenta como el componente de grano. Los frijoles que lleva dentro no sustituyen el vegetal.', '[{"item": "Arroz blanco de grano largo", "qty": "6 lb"}, {"item": "Frijoles negros cocidos, con su caldo", "qty": "2 cuartos"}, {"item": "Sofrito", "qty": "3 tazas"}, {"item": "Agua o caldo de los frijoles sin sal", "qty": "3½ galones"}, {"item": "Laurel", "qty": "4 hojas"}]', '["Combine el sofrito, los frijoles y el líquido; lleve a fuego lento.", "Agregue el arroz, tape y cocine hasta que esté tierno, unos 25 minutos.", "Deje reposar 5 minutos, suelte con tenedor y mantenga a 135°F o más."]', '45 cups cooked', '45 tazas cocidas', 'congr');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_black_beans_stewed', 'Black beans, stewed (½ cup vegetable portion)', 'Cook Monday for the week. Portion ½ cup with liquid.', '[{"item": "Dry black beans", "qty": "3½ lb"}, {"item": "Water", "qty": "2 gal"}, {"item": "Sofrito", "qty": "3 cups"}, {"item": "Bay leaf", "qty": "4"}, {"item": "Cumin", "qty": "1 tbsp"}]', '["Soak beans overnight in cold water under refrigeration, or use the quick-soak method.", "Simmer in fresh water until tender, 1½ to 2 hours. Do not salt while cooking.", "Add sofrito, bay and cumin; simmer 20 minutes more until the liquid thickens."]', '["adult_day_care", "base", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Frijoles negros guisados (porción de vegetal ½ taza)', 'Se cocinan el lunes para toda la semana. Porción de ½ taza con su caldo.', '[{"item": "Frijoles negros secos", "qty": "3½ lb"}, {"item": "Agua", "qty": "2 galones"}, {"item": "Sofrito", "qty": "3 tazas"}, {"item": "Laurel", "qty": "4 hojas"}, {"item": "Comino", "qty": "1 cda"}]', '["Remoje los frijoles toda la noche en agua fría dentro del refrigerador, o use el método de remojo rápido.", "Hierva a fuego lento en agua fresca hasta que estén blandos, de 1½ a 2 horas. No agregue sal durante la cocción.", "Agregue el sofrito, el laurel y el comino; cocine 20 minutos más hasta que el caldo espese."]', '45 portions (about 6 qt)', '45 porciones (unos 6 cuartos)', 'black_beans_stewed');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_pollo_guisado', 'Pollo guisado', 'Chicken should fall apart with a fork. Nothing on this menu needs a knife.', '[{"item": "Boneless skinless chicken thigh", "qty": "12 lb raw"}, {"item": "Sofrito", "qty": "6 cups"}, {"item": "Carrot, ½-inch dice", "qty": "5 lb"}, {"item": "Potato, ½-inch dice", "qty": "5 lb"}, {"item": "Unsalted chicken broth", "qty": "2 qt"}, {"item": "Bay leaf", "qty": "4"}]', '["Cut thighs into 1½-inch pieces. Sear in batches in a hot rondeau, then remove.", "Return chicken to the pot with sofrito, broth and bay. Simmer covered 25 minutes.", "Add carrot and potato. Simmer 20 to 25 minutes until the vegetables are fork tender and the chicken shreds under a spoon.", "Check the thickest piece: 165°F for 15 seconds. Hold at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Pollo guisado', 'El pollo debe deshacerse con un tenedor. Nada en este menú debe necesitar cuchillo.', '[{"item": "Muslo de pollo sin hueso ni piel", "qty": "12 lb crudas"}, {"item": "Sofrito", "qty": "6 tazas"}, {"item": "Zanahoria en cubos de ½ pulgada", "qty": "5 lb"}, {"item": "Papa en cubos de ½ pulgada", "qty": "5 lb"}, {"item": "Caldo de pollo sin sal", "qty": "2 cuartos"}, {"item": "Laurel", "qty": "4 hojas"}]', '["Corte los muslos en trozos de 1½ pulgada. Selle por tandas en olla caliente y retire.", "Devuelva el pollo a la olla con el sofrito, el caldo y el laurel. Cocine tapado 25 minutos.", "Agregue la zanahoria y la papa. Cocine de 20 a 25 minutos hasta que el vegetal esté tierno y el pollo se deshaga con la cuchara.", "Verifique el trozo más grueso: 165°F por 15 segundos. Mantenga a 135°F o más."]', 'Stewed chicken thigh 3 oz · carrots and potato ½ cup · white rice 1 cup · mandarin oranges ½ cup · milk', 'Muslo de pollo guisado 3 oz · zanahoria y papa ½ taza · arroz blanco 1 taza · mandarina ½ taza · leche', 'pollo_guisado');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_picadillo', 'Picadillo', 'Rinse the olives to cut sodium. Raisins add the traditional sweetness without sugar.', '[{"item": "Ground beef, 85/15", "qty": "13 lb raw"}, {"item": "Sofrito", "qty": "6 cups"}, {"item": "Golden raisins", "qty": "1½ cups"}, {"item": "Green olives, sliced, rinsed", "qty": "1 cup"}, {"item": "Potato, small dice (optional)", "qty": "3 lb"}, {"item": "Green beans, cut, frozen", "qty": "8 lb"}]', '["Brown the beef in batches, breaking it fine. Drain the fat.", "Add sofrito, raisins and rinsed olives. Simmer 20 minutes until thick, not wet.", "Cook to 160°F. Steam the green beans separately until tender, 6 to 8 minutes.", "Hold both at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Picadillo', 'Enjuague las aceitunas para bajar el sodio. Las pasas dan el dulzor tradicional sin azúcar.', '[{"item": "Carne molida de res 85/15", "qty": "13 lb crudas"}, {"item": "Sofrito", "qty": "6 tazas"}, {"item": "Pasas rubias", "qty": "1½ tazas"}, {"item": "Aceitunas verdes en rodajas, enjuagadas", "qty": "1 taza"}, {"item": "Papa en cubitos (opcional)", "qty": "3 lb"}, {"item": "Habichuelas cortadas, congeladas", "qty": "8 lb"}]', '["Dore la carne por tandas, desmenuzándola fina. Escurra la grasa.", "Agregue el sofrito, las pasas y las aceitunas enjuagadas. Cocine 20 minutos hasta que espese; no debe quedar aguado.", "Cocine a 160°F. Aparte, cocine las habichuelas al vapor de 6 a 8 minutos hasta que estén tiernas.", "Mantenga todo a 135°F o más."]', 'Ground beef in sofrito 3 oz · green beans ½ cup · white rice 1 cup · banana ½ cup · milk', 'Carne molida en sofrito 3 oz · habichuelas ½ taza · arroz blanco 1 taza · plátano ½ taza · leche', 'picadillo');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_picadillo_a_la_habanera', 'Picadillo a la habanera', 'Squash is soft by nature, which is why it repeats on this menu.', '[{"item": "Ground beef, 85/15", "qty": "13 lb raw"}, {"item": "Sofrito", "qty": "6 cups"}, {"item": "Golden raisins", "qty": "1½ cups"}, {"item": "Green olives, sliced, rinsed", "qty": "1½ cups"}, {"item": "Calabaza or butternut squash, 1-inch dice", "qty": "9 lb"}]', '["Brown the beef, drain, add sofrito, raisins and olives; simmer 20 minutes.", "Roast or steam the squash until fork tender, 20 to 25 minutes.", "Cook beef to 160°F. Hold both at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Picadillo a la habanera', 'La calabaza es blanda por naturaleza; por eso se repite en este menú.', '[{"item": "Carne molida de res 85/15", "qty": "13 lb crudas"}, {"item": "Sofrito", "qty": "6 tazas"}, {"item": "Pasas rubias", "qty": "1½ tazas"}, {"item": "Aceitunas verdes enjuagadas", "qty": "1½ tazas"}, {"item": "Calabaza en cubos de 1 pulgada", "qty": "9 lb"}]', '["Dore la carne, escurra, agregue el sofrito, las pasas y las aceitunas; cocine 20 minutos.", "Ase o cocine al vapor la calabaza de 20 a 25 minutos hasta que esté tierna.", "Carne a 160°F. Mantenga todo a 135°F o más."]', 'Ground beef with olives and raisins 3 oz · calabaza ½ cup · white rice 1 cup · pear ½ cup · milk', 'Carne molida con aceitunas y pasas 3 oz · calabaza ½ taza · arroz blanco 1 taza · pera ½ taza · leche', 'picadillo_a_la_habanera');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_turkey_picadillo', 'Turkey picadillo', 'The lightest lunch on the cycle; it follows a heavier pork day.', '[{"item": "Ground turkey, 93/7", "qty": "13 lb raw"}, {"item": "Sofrito", "qty": "6 cups"}, {"item": "Golden raisins", "qty": "1 cup"}, {"item": "Frozen mixed vegetables", "qty": "8 lb"}, {"item": "Olive oil", "qty": "½ cup"}]', '["Brown the turkey in oil; it is lean and sticks easily, so keep it moving.", "Add sofrito and raisins; simmer 15 minutes. Turkey dries out, so keep it saucy.", "Cook to 165°F. Steam the vegetables until tender. Hold both at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Turkey picadillo (picadillo de pavo)', 'Es el almuerzo más ligero del ciclo; va después de un día de cerdo.', '[{"item": "Pavo molido 93/7", "qty": "13 lb crudas"}, {"item": "Sofrito", "qty": "6 tazas"}, {"item": "Pasas rubias", "qty": "1 taza"}, {"item": "Vegetales mixtos congelados", "qty": "8 lb"}, {"item": "Aceite de oliva", "qty": "½ taza"}]', '["Dore el pavo en el aceite; es magro y se pega fácil, muévalo constantemente.", "Agregue el sofrito y las pasas; cocine 15 minutos. El pavo se reseca, manténgalo jugoso.", "Cocine a 165°F. Cocine los vegetales al vapor. Mantenga todo a 135°F o más."]', 'Ground turkey in sofrito 3 oz · mixed vegetables ½ cup · white rice 1 cup · peaches ½ cup · milk', 'Pavo molido en sofrito 3 oz · vegetales mixtos ½ taza · arroz blanco 1 taza · melocotón ½ taza · leche', 'turkey_picadillo');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_ropa_vieja', 'Ropa vieja', 'Cook the beef the day before; it shreds better cold and saves the morning.', '[{"item": "Beef chuck or flank", "qty": "15 lb raw"}, {"item": "Sofrito", "qty": "8 cups"}, {"item": "Red and green bell pepper, strips", "qty": "6 lb"}, {"item": "Onion, sliced", "qty": "4 lb"}, {"item": "Unsalted beef broth", "qty": "3 qt"}, {"item": "Bay leaf", "qty": "6"}]', '["Simmer the beef in broth with bay until it shreds, 2½ to 3 hours. Cool slightly in its liquid.", "Shred with two forks; discard fat and gristle.", "Sauté peppers and onions until soft; add sofrito and the shredded beef with 1 qt of its cooking liquid. Simmer 20 minutes.", "Reheat to 165°F if it cooled. Hold at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Ropa vieja', 'Cocine la carne el día anterior; se deshebra mejor fría y le ahorra la mañana.', '[{"item": "Falda o aguja de res", "qty": "15 lb crudas"}, {"item": "Sofrito", "qty": "8 tazas"}, {"item": "Ají rojo y verde en tiras", "qty": "6 lb"}, {"item": "Cebolla en tiras", "qty": "4 lb"}, {"item": "Caldo de res sin sal", "qty": "3 cuartos"}, {"item": "Laurel", "qty": "6 hojas"}]', '["Cocine la carne en el caldo con laurel hasta que se deshebre, de 2½ a 3 horas. Deje enfriar un poco en su líquido.", "Deshebre con dos tenedores; retire grasa y nervios.", "Sofría el ají y la cebolla hasta que estén blandos; agregue el sofrito y la carne con 1 cuarto de su caldo. Cocine 20 minutos.", "Si se enfrió, recaliente a 165°F. Mantenga a 135°F o más."]', 'Shredded beef in criolla sauce 3 oz · peppers and onions ½ cup · white rice 1 cup · applesauce ½ cup · milk', 'Carne deshebrada en salsa criolla 3 oz · ají y cebolla ½ taza · arroz blanco 1 taza · puré de manzana ½ taza · leche', 'ropa_vieja');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_carne_con_papas', 'Carne con papas', 'Cut the beef small, 1 inch or less, so it needs no knife.', '[{"item": "Beef chuck, 1-inch cubes", "qty": "15 lb raw"}, {"item": "Sofrito", "qty": "8 cups"}, {"item": "Potato, 1-inch dice", "qty": "8 lb"}, {"item": "Carrot, ½-inch dice", "qty": "4 lb"}, {"item": "Unsalted beef broth", "qty": "3 qt"}]', '["Sear the beef in batches. Add sofrito and broth; simmer covered 2 hours until tender.", "Add potato and carrot; simmer 25 minutes until the potatoes give way under a spoon.", "Cook to 145°F, then hold at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Carne con papas', 'Corte la carne pequeña, de 1 pulgada o menos, para que no haga falta cuchillo.', '[{"item": "Aguja de res en cubos de 1 pulgada", "qty": "15 lb crudas"}, {"item": "Sofrito", "qty": "8 tazas"}, {"item": "Papa en cubos de 1 pulgada", "qty": "8 lb"}, {"item": "Zanahoria en cubos", "qty": "4 lb"}, {"item": "Caldo de res sin sal", "qty": "3 cuartos"}]', '["Selle la carne por tandas. Agregue el sofrito y el caldo; cocine tapado 2 horas hasta que esté tierna.", "Agregue la papa y la zanahoria; cocine 25 minutos hasta que la papa ceda con la cuchara.", "Cocine a 145°F y mantenga a 135°F o más."]', 'Beef stewed with potatoes 3 oz · potato and carrot ½ cup · white rice 1 cup · pineapple ½ cup · milk', 'Res guisada con papas 3 oz · papa y zanahoria ½ taza · arroz blanco 1 taza · piña ½ taza · leche', 'carne_con_papas');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_alb_ndigas_en_salsa', 'Albóndigas en salsa', 'Contains egg and wheat from the binder. Label it.', '[{"item": "Ground turkey, 93/7", "qty": "13 lb raw"}, {"item": "Breadcrumbs, plain", "qty": "3 cups"}, {"item": "Eggs", "qty": "8"}, {"item": "Garlic, minced", "qty": "½ cup"}, {"item": "Parsley, chopped", "qty": "1 cup"}, {"item": "Sofrito", "qty": "6 cups"}, {"item": "Yellow squash or calabaza, sliced", "qty": "8 lb"}]', '["Mix turkey, breadcrumbs, eggs, garlic and parsley. Portion 1½ oz meatballs, 2 per serving.", "Bake at 375°F for 18 to 20 minutes until 165°F.", "Simmer the meatballs in sofrito 10 minutes so they stay moist. Steam the squash until tender.", "Hold at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Albóndigas en salsa', 'Contiene huevo y trigo por el pan rallado. Anótelo en la etiqueta.', '[{"item": "Pavo molido 93/7", "qty": "13 lb crudas"}, {"item": "Pan rallado sin sabor", "qty": "3 tazas"}, {"item": "Huevos", "qty": "8"}, {"item": "Ajo picado", "qty": "½ taza"}, {"item": "Perejil picado", "qty": "1 taza"}, {"item": "Sofrito", "qty": "6 tazas"}, {"item": "Calabacín o calabaza en rodajas", "qty": "8 lb"}]', '["Mezcle el pavo, el pan rallado, los huevos, el ajo y el perejil. Forme albóndigas de 1½ oz, 2 por porción.", "Hornee a 375°F de 18 a 20 minutos hasta 165°F.", "Cocine las albóndigas en el sofrito 10 minutos para que queden jugosas. Cocine el calabacín al vapor.", "Mantenga a 135°F o más."]', 'Turkey meatballs 3 oz · squash ½ cup · white rice 1 cup · orange sections ½ cup · milk', 'Albóndigas de pavo 3 oz · calabacín ½ taza · arroz blanco 1 taza · gajos de naranja ½ taza · leche', 'alb_ndigas_en_salsa');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_fricas_de_pollo', 'Fricasé de pollo', 'Close to pollo guisado but with olives; keep them apart on the cycle.', '[{"item": "Boneless skinless chicken thigh", "qty": "12 lb raw"}, {"item": "Sofrito", "qty": "7 cups"}, {"item": "Potato, diced", "qty": "5 lb"}, {"item": "Carrot, diced", "qty": "4 lb"}, {"item": "Green olives, rinsed", "qty": "1 cup"}, {"item": "Unsalted chicken broth", "qty": "2 qt"}]', '["Brown the chicken, add sofrito, broth and olives, simmer 25 minutes.", "Add potato and carrot; simmer 25 minutes until tender.", "Cook to 165°F. Hold at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Fricasé de pollo', 'Se parece al pollo guisado pero con aceitunas; manténgalos separados en el ciclo.', '[{"item": "Muslo de pollo sin hueso ni piel", "qty": "12 lb crudas"}, {"item": "Sofrito", "qty": "7 tazas"}, {"item": "Papa en cubos", "qty": "5 lb"}, {"item": "Zanahoria en cubos", "qty": "4 lb"}, {"item": "Aceitunas verdes enjuagadas", "qty": "1 taza"}, {"item": "Caldo de pollo sin sal", "qty": "2 cuartos"}]', '["Dore el pollo, agregue el sofrito, el caldo y las aceitunas, cocine 25 minutos.", "Agregue la papa y la zanahoria; cocine 25 minutos hasta que estén tiernas.", "Cocine a 165°F. Mantenga a 135°F o más."]', 'Chicken fricassee 3 oz · potato and carrot ½ cup · white rice 1 cup · pear ½ cup · milk', 'Fricasé de pollo 3 oz · papa y zanahoria ½ taza · arroz blanco 1 taza · pera ½ taza · leche', 'fricas_de_pollo');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_arroz_con_pollo', 'Arroz con pollo', 'The rice here is the grain component; do not add a second rice.', '[{"item": "Boneless skinless chicken thigh", "qty": "12 lb raw"}, {"item": "Long grain rice", "qty": "6 lb"}, {"item": "Sofrito", "qty": "6 cups"}, {"item": "Unsalted chicken broth", "qty": "4 qt"}, {"item": "Bijol or turmeric", "qty": "3 tbsp"}, {"item": "Frozen peas and carrots", "qty": "6 lb"}]', '["Brown the chicken, remove. Toast the rice briefly in the pot with sofrito and bijol.", "Add broth and the chicken. Cover and cook 25 minutes until the rice is tender.", "Fold in the peas and carrots in the last 5 minutes.", "Chicken to 165°F. Hold at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Arroz con pollo', 'Aquí el arroz es el componente de grano; no agregue un segundo arroz.', '[{"item": "Muslo de pollo sin hueso ni piel", "qty": "12 lb crudas"}, {"item": "Arroz de grano largo", "qty": "6 lb"}, {"item": "Sofrito", "qty": "6 tazas"}, {"item": "Caldo de pollo sin sal", "qty": "4 cuartos"}, {"item": "Bijol o cúrcuma", "qty": "3 cdas"}, {"item": "Petit pois y zanahoria congelados", "qty": "6 lb"}]', '["Dore el pollo y retírelo. Tueste brevemente el arroz en la olla con el sofrito y el bijol.", "Agregue el caldo y el pollo. Tape y cocine 25 minutos hasta que el arroz esté tierno.", "Incorpore el petit pois y la zanahoria en los últimos 5 minutos.", "Pollo a 165°F. Mantenga a 135°F o más."]', 'Chicken with yellow rice 3 oz · peas and carrots ½ cup · yellow rice 1 cup · melon ½ cup · milk', 'Pollo con arroz amarillo 3 oz · petit pois y zanahoria ½ taza · arroz amarillo 1 taza · melón ½ taza · leche', 'arroz_con_pollo');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_pollo_asado_with_congr', 'Pollo asado with congrí', 'Marinate the day before. Roasting pans go in as the stews come out.', '[{"item": "Boneless skinless chicken thigh", "qty": "12 lb raw"}, {"item": "Garlic, minced", "qty": "¾ cup"}, {"item": "Sour orange or lime juice", "qty": "2 cups"}, {"item": "Dried oregano", "qty": "3 tbsp"}, {"item": "Olive oil", "qty": "¾ cup"}, {"item": "Calabaza, 1-inch dice", "qty": "9 lb"}, {"item": "Congrí", "qty": "45 cups"}]', '["Marinate the thighs in garlic, citrus, oregano and oil at least 4 hours, refrigerated.", "Roast at 400°F for 25 to 30 minutes until 165°F, then slice or leave whole if tender.", "Roast the calabaza alongside until soft.", "Hold at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Pollo asado con congrí', 'Adobe el día anterior. Las bandejas entran al horno cuando salen los guisos.', '[{"item": "Muslo de pollo sin hueso ni piel", "qty": "12 lb crudas"}, {"item": "Ajo picado", "qty": "¾ taza"}, {"item": "Naranja agria o limón", "qty": "2 tazas"}, {"item": "Orégano seco", "qty": "3 cdas"}, {"item": "Aceite de oliva", "qty": "¾ taza"}, {"item": "Calabaza en cubos de 1 pulgada", "qty": "9 lb"}, {"item": "Congrí", "qty": "45 tazas"}]', '["Adobe los muslos con ajo, cítrico, orégano y aceite al menos 4 horas, refrigerados.", "Ase a 400°F de 25 a 30 minutos hasta 165°F; rebane o deje entero si está tierno.", "Ase la calabaza al mismo tiempo hasta que esté blanda.", "Mantenga a 135°F o más."]', 'Roast chicken thigh 3 oz · calabaza ½ cup · congrí 1 cup · banana ½ cup · milk', 'Muslo de pollo asado 3 oz · calabaza ½ taza · congrí 1 taza · plátano ½ taza · leche', 'pollo_asado_with_congr');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_lech_n_asado', 'Lechón asado', 'Best cooked the day before. The no-pork version replaces this with baked chicken tenders.', '[{"item": "Pork shoulder (Boston butt), bone in", "qty": "22 lb raw"}, {"item": "Garlic, minced", "qty": "1½ cups"}, {"item": "Sour orange or lime juice", "qty": "3 cups"}, {"item": "Dried oregano", "qty": "¼ cup"}, {"item": "Onion, sliced", "qty": "4 lb"}, {"item": "Black beans, stewed", "qty": "45 portions"}]', '["Marinate the pork overnight in mojo: garlic, citrus, oregano and onion.", "Roast covered at 300°F for 4 to 5 hours until it pulls apart, internal 195°F to 203°F for shredding.", "Rest 30 minutes, shred, discard fat. Moisten with the pan juices, skimmed.", "Hold at 135°F or above, or cool per the cooling rule and reheat to 165°F."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Lechón asado', 'Mejor cocinarlo el día anterior. La versión sin cerdo lo sustituye por tiras de pollo al horno.', '[{"item": "Masa de cerdo (Boston butt), con hueso", "qty": "22 lb crudas"}, {"item": "Ajo picado", "qty": "1½ tazas"}, {"item": "Naranja agria o limón", "qty": "3 tazas"}, {"item": "Orégano seco", "qty": "¼ taza"}, {"item": "Cebolla en rodajas", "qty": "4 lb"}, {"item": "Frijoles negros guisados", "qty": "45 porciones"}]', '["Adobe el cerdo toda la noche en mojo: ajo, cítrico, orégano y cebolla.", "Ase tapado a 300°F de 4 a 5 horas hasta que se deshaga, temperatura interna de 195°F a 203°F para deshebrar.", "Deje reposar 30 minutos, deshebre y retire la grasa. Humedezca con el jugo de la bandeja, desgrasado.", "Mantenga a 135°F o más, o enfríe según la regla y recaliente a 165°F."]', 'Shredded roast pork 3 oz · black beans ½ cup · white rice 1 cup · applesauce ½ cup · milk', 'Cerdo asado deshebrado 3 oz · frijoles negros ½ taza · arroz blanco 1 taza · puré de manzana ½ taza · leche', 'lech_n_asado');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_cerdo_guisado', 'Cerdo guisado', 'Trim hard fat before cubing; older adults eat less of it and it holds heat unevenly.', '[{"item": "Pork shoulder, 1-inch cubes", "qty": "18 lb raw"}, {"item": "Sofrito", "qty": "8 cups"}, {"item": "Unsalted broth", "qty": "3 qt"}, {"item": "Calabaza, diced", "qty": "9 lb"}]', '["Sear the pork, add sofrito and broth, simmer covered 2 to 2½ hours until fork tender.", "Steam or roast the calabaza until soft.", "Pork to 145°F minimum; braised to tender is well past that. Hold at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Cerdo guisado', 'Recorte la grasa dura antes de cortar; los adultos mayores la comen menos y no calienta parejo.', '[{"item": "Masa de cerdo en cubos de 1 pulgada", "qty": "18 lb crudas"}, {"item": "Sofrito", "qty": "8 tazas"}, {"item": "Caldo sin sal", "qty": "3 cuartos"}, {"item": "Calabaza en cubos", "qty": "9 lb"}]', '["Selle el cerdo, agregue el sofrito y el caldo, cocine tapado de 2 a 2½ horas hasta que esté tierno.", "Cocine la calabaza al vapor o al horno hasta que esté blanda.", "Cerdo a 145°F como mínimo; guisado queda muy por encima. Mantenga a 135°F o más."]', 'Braised pork shoulder 3 oz · calabaza ½ cup · white rice 1 cup · banana ½ cup · milk', 'Masa de cerdo guisada 3 oz · calabaza ½ taza · arroz blanco 1 taza · plátano ½ taza · leche', 'cerdo_guisado');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_potaje_de_lentejas', 'Potaje de lentejas', 'A meatless lunch when the smoked meat is left out. Lentils count as the protein.', '[{"item": "Dry lentils", "qty": "7 lb"}, {"item": "Sofrito", "qty": "8 cups"}, {"item": "Carrot, diced", "qty": "4 lb"}, {"item": "Potato, diced", "qty": "4 lb"}, {"item": "Smoked turkey or ham hock (optional)", "qty": "3 lb"}, {"item": "Water", "qty": "4 gal"}]', '["Simmer lentils in water 25 minutes; they need no soaking.", "Add sofrito, carrot, potato and the smoked meat if used. Simmer 30 minutes until everything is soft.", "Hold at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Potaje de lentejas', 'Es un almuerzo sin carne si se omite el ahumado. Las lentejas cuentan como la proteína.', '[{"item": "Lentejas secas", "qty": "7 lb"}, {"item": "Sofrito", "qty": "8 tazas"}, {"item": "Zanahoria en cubos", "qty": "4 lb"}, {"item": "Papa en cubos", "qty": "4 lb"}, {"item": "Pavo ahumado o jamón (opcional)", "qty": "3 lb"}, {"item": "Agua", "qty": "4 galones"}]', '["Cocine las lentejas en agua 25 minutos; no necesitan remojo.", "Agregue el sofrito, la zanahoria, la papa y la carne ahumada si la usa. Cocine 30 minutos hasta que todo esté blando.", "Mantenga a 135°F o más."]', 'Lentil and vegetable stew 1 cup · vegetables in the stew ½ cup · Cuban bread 2 oz eq · pear ½ cup · milk', 'Potaje de lentejas y vegetales 1 taza · vegetales del potaje ½ taza · pan cubano 2 oz eq · pera ½ taza · leche', 'potaje_de_lentejas');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_potaje_de_garbanzos', 'Potaje de garbanzos', 'Rinsing cuts the sodium substantially. Never skip it.', '[{"item": "Canned chickpeas, drained and rinsed", "qty": "6 #10 cans"}, {"item": "Sofrito", "qty": "8 cups"}, {"item": "Potato, diced", "qty": "5 lb"}, {"item": "Calabaza, diced", "qty": "4 lb"}, {"item": "Smoked turkey (optional)", "qty": "3 lb"}, {"item": "Unsalted broth", "qty": "2 gal"}]', '["Rinse the chickpeas well; canned sodium washes off.", "Simmer with sofrito, broth, potato and squash 40 minutes until the potato breaks at the edges.", "Hold at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Potaje de garbanzos', 'Enjuagar baja bastante el sodio. Nunca lo omita.', '[{"item": "Garbanzos en lata, escurridos y enjuagados", "qty": "6 latas #10"}, {"item": "Sofrito", "qty": "8 tazas"}, {"item": "Papa en cubos", "qty": "5 lb"}, {"item": "Calabaza en cubos", "qty": "4 lb"}, {"item": "Pavo ahumado (opcional)", "qty": "3 lb"}, {"item": "Caldo sin sal", "qty": "2 galones"}]', '["Enjuague bien los garbanzos; el sodio de la lata se va con el agua.", "Cocine con el sofrito, el caldo, la papa y la calabaza 40 minutos hasta que la papa se deshaga en los bordes.", "Mantenga a 135°F o más."]', 'Chickpea and vegetable stew 1 cup · vegetables in the stew ½ cup · Cuban bread 2 oz eq · peaches ½ cup · milk', 'Potaje de garbanzos y vegetales 1 taza · vegetales del potaje ½ taza · pan cubano 2 oz eq · melocotón ½ taza · leche', 'potaje_de_garbanzos');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_sopa_de_pollo', 'Sopa de pollo', 'Pack the noodles under the soup. Soup also helps hydration, which is why Friday is soup.', '[{"item": "Boneless skinless chicken thigh", "qty": "12 lb raw"}, {"item": "Unsalted chicken broth", "qty": "5 gal"}, {"item": "Carrot, sliced", "qty": "4 lb"}, {"item": "Celery, sliced thin", "qty": "2 lb"}, {"item": "Potato, diced", "qty": "4 lb"}, {"item": "Fine egg noodles or fideos", "qty": "4 lb"}, {"item": "Sofrito", "qty": "4 cups"}]', '["Poach the chicken in the broth 25 minutes, remove and shred.", "Add sofrito and vegetables; simmer 20 minutes until very soft.", "Cook the noodles separately and add at packing, or they swell and drink the broth.", "Return the chicken, reheat to 165°F, hold at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Sopa de pollo', 'Empaque los fideos debajo de la sopa. La sopa también ayuda a la hidratación; por eso el viernes es de sopa.', '[{"item": "Muslo de pollo sin hueso ni piel", "qty": "12 lb crudas"}, {"item": "Caldo de pollo sin sal", "qty": "5 galones"}, {"item": "Zanahoria en rodajas", "qty": "4 lb"}, {"item": "Apio en rodajas finas", "qty": "2 lb"}, {"item": "Papa en cubos", "qty": "4 lb"}, {"item": "Fideos finos", "qty": "4 lb"}, {"item": "Sofrito", "qty": "4 tazas"}]', '["Cocine el pollo en el caldo 25 minutos, retire y deshebre.", "Agregue el sofrito y los vegetales; cocine 20 minutos hasta que estén muy blandos.", "Cocine los fideos aparte y agréguelos al empacar, o se hinchan y se beben el caldo.", "Devuelva el pollo, recaliente a 165°F y mantenga a 135°F o más."]', 'Chicken soup with shredded chicken 3 oz · carrots, celery, potato ½ cup · soup noodles 1 cup · applesauce ½ cup · milk', 'Sopa con pollo deshebrado 3 oz · zanahoria, apio y papa ½ taza · fideos 1 taza · puré de manzana ½ taza · leche', 'sopa_de_pollo');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_baked_fish_with_lemon_and_garlic', 'Baked fish with lemon and garlic', 'Bake fish last, closest to packing time. It does not hold well.', '[{"item": "Tilapia fillets, 4 oz each", "qty": "12 lb raw"}, {"item": "Olive oil", "qty": "1 cup"}, {"item": "Garlic, minced", "qty": "¾ cup"}, {"item": "Lemon juice", "qty": "2 cups"}, {"item": "Paprika", "qty": "3 tbsp"}, {"item": "Green beans, cut", "qty": "8 lb"}, {"item": "Brown rice", "qty": "6 lb"}]', '["Lay the fillets in oiled pans; brush with oil, garlic, lemon and paprika.", "Bake at 400°F for 10 to 12 minutes to 145°F. Fish overcooks fast; set a timer.", "Steam the beans, cook the brown rice. Hold everything at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Pescado al horno con limón y ajo', 'Hornee el pescado de último, lo más cerca posible de la hora de empacar. No aguanta bien.', '[{"item": "Filetes de tilapia de 4 oz", "qty": "12 lb crudas"}, {"item": "Aceite de oliva", "qty": "1 taza"}, {"item": "Ajo picado", "qty": "¾ taza"}, {"item": "Jugo de limón", "qty": "2 tazas"}, {"item": "Paprika", "qty": "3 cdas"}, {"item": "Habichuelas cortadas", "qty": "8 lb"}, {"item": "Arroz integral", "qty": "6 lb"}]', '["Coloque los filetes en bandejas aceitadas; pinte con aceite, ajo, limón y paprika.", "Hornee a 400°F de 10 a 12 minutos hasta 145°F. El pescado se pasa rápido; ponga temporizador.", "Cocine las habichuelas al vapor y el arroz integral. Mantenga todo a 135°F o más."]', 'Baked tilapia 3 oz · green beans ½ cup · brown rice 1 cup WG · orange sections ½ cup · milk', 'Tilapia al horno 3 oz · habichuelas ½ taza · arroz integral 1 taza WG · gajos de naranja ½ taza · leche', 'baked_fish_with_lemon_and_garlic');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_pescado_en_salsa_criolla', 'Pescado en salsa criolla', 'The sauce keeps the fish moist in transport better than plain baked fish.', '[{"item": "Tilapia fillets", "qty": "12 lb raw"}, {"item": "Sofrito", "qty": "6 cups"}, {"item": "Bell pepper, strips", "qty": "4 lb"}, {"item": "Onion, sliced", "qty": "3 lb"}, {"item": "Lime juice", "qty": "1 cup"}]', '["Sauté peppers and onions; add sofrito and lime, simmer 10 minutes.", "Lay the fillets in pans, spoon the sauce over, bake at 375°F for 12 to 15 minutes to 145°F.", "Hold at 135°F or above."]', '["adult_day_care", "lunch", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Pescado en salsa criolla', 'La salsa mantiene el pescado jugoso en el transporte mejor que el pescado al horno solo.', '[{"item": "Filetes de tilapia", "qty": "12 lb crudas"}, {"item": "Sofrito", "qty": "6 tazas"}, {"item": "Ají en tiras", "qty": "4 lb"}, {"item": "Cebolla en tiras", "qty": "3 lb"}, {"item": "Jugo de limón", "qty": "1 taza"}]', '["Sofría el ají y la cebolla; agregue el sofrito y el limón, cocine 10 minutos.", "Coloque los filetes en bandejas, cubra con la salsa y hornee a 375°F de 12 a 15 minutos hasta 145°F.", "Mantenga a 135°F o más."]', 'Fish in creole sauce 3 oz · peppers and onions ½ cup · white rice 1 cup · strawberries ½ cup · milk', 'Pescado en salsa criolla 3 oz · ají y cebolla ½ taza · arroz blanco 1 taza · fresa ½ taza · leche', 'pescado_en_salsa_criolla');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_oatmeal_with_cinnamon', 'Oatmeal with cinnamon', 'Oatmeal thickens as it sits; loosen with hot water before portioning.', '[{"item": "Old-fashioned oats", "qty": "5 lb"}, {"item": "Water", "qty": "3 gal"}, {"item": "Cinnamon", "qty": "3 tbsp"}, {"item": "Eggs", "qty": "4 dozen"}, {"item": "Melon, diced", "qty": "9 lb"}]', '["Simmer oats and water 5 minutes; stir in cinnamon. No sugar is added.", "Scramble the eggs soft; they firm up in transport. Cook to 160°F.", "Portion 1 cup oatmeal, 1 egg, ½ cup fruit, and one 8 oz milk."]', '["adult_day_care", "breakfast", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Avena con canela', 'La avena espesa al reposar; aflójela con agua caliente antes de servir.', '[{"item": "Avena en hojuelas", "qty": "5 lb"}, {"item": "Agua", "qty": "3 galones"}, {"item": "Canela", "qty": "3 cdas"}, {"item": "Huevos", "qty": "4 docenas"}, {"item": "Melón en cubos", "qty": "9 lb"}]', '["Cocine la avena con agua 5 minutos; agregue la canela. No se agrega azúcar.", "Revuelva los huevos suaves; se cuajan más en el transporte. Cocine a 160°F.", "Sirva 1 taza de avena, 1 huevo, ½ taza de fruta y una leche de 8 oz."]', 'Oatmeal 1 cup WG · scrambled egg 1 · melon ½ cup · milk 1 cup', 'Avena 1 taza WG · huevo revuelto 1 · melón ½ taza · leche 1 taza', 'oatmeal_with_cinnamon');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_oatmeal_and_yogurt', 'Oatmeal and yogurt', 'Yogurt must be 12 g added sugar or less per 6 oz.', '[{"item": "Old-fashioned oats", "qty": "5 lb"}, {"item": "Low-fat yogurt, 6 oz cups", "qty": "45"}, {"item": "Strawberries, sliced", "qty": "9 lb"}]', '["Cook the oatmeal as above.", "Slice the strawberries; they must be sliced, never whole, for safe swallowing.", "Yogurt stays sealed in its cup and goes in cold, under 41°F."]', '["adult_day_care", "breakfast", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Avena y yogur', 'El yogur debe tener 12 g de azúcar añadida o menos por cada 6 oz.', '[{"item": "Avena en hojuelas", "qty": "5 lb"}, {"item": "Yogur bajo en grasa, vasitos de 6 oz", "qty": "45"}, {"item": "Fresas en rodajas", "qty": "9 lb"}]', '["Cocine la avena como arriba.", "Rebane las fresas; deben ir rebanadas, nunca enteras, para tragar seguro.", "El yogur va sellado en su vasito y frío, por debajo de 41°F."]', 'Oatmeal 1 cup WG · low-fat yogurt 6 oz · strawberries ½ cup · milk 1 cup', 'Avena 1 taza WG · yogur bajo en grasa 6 oz · fresa ½ taza · leche 1 taza', 'oatmeal_and_yogurt');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_oatmeal_and_cottage_cheese', 'Oatmeal and cottage cheese', 'Keep the cold items in a separate cold pack from the hot oatmeal.', '[{"item": "Old-fashioned oats", "qty": "5 lb"}, {"item": "Low-fat cottage cheese", "qty": "2 #10 tubs (about 14 lb)"}, {"item": "Sliced peaches in juice", "qty": "3 #10 cans"}]', '["Cook the oatmeal as above.", "Portion cottage cheese ½ cup into a cold cup.", "Drain the peaches; the juice is not served as a drink."]', '["adult_day_care", "breakfast", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Avena y requesón', 'Mantenga los fríos en una bolsa aparte de la avena caliente.', '[{"item": "Avena en hojuelas", "qty": "5 lb"}, {"item": "Requesón bajo en grasa", "qty": "2 envases grandes (unas 14 lb)"}, {"item": "Melocotón en jugo", "qty": "3 latas #10"}]', '["Cocine la avena como arriba.", "Sirva ½ taza de requesón en vasito frío.", "Escurra el melocotón; el jugo no se sirve como bebida."]', 'Oatmeal 1 cup WG · low-fat cottage cheese ½ cup · peaches in juice ½ cup · milk 1 cup', 'Avena 1 taza WG · requesón bajo en grasa ½ taza · melocotón en jugo ½ taza · leche 1 taza', 'oatmeal_and_cottage_cheese');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_cream_of_wheat_and_yogurt', 'Cream of wheat and yogurt', 'This is the one non-whole-grain cereal day; the whole grain that day comes at lunch.', '[{"item": "Cream of wheat, enriched", "qty": "4 lb"}, {"item": "Water", "qty": "3 gal"}, {"item": "Low-fat yogurt, 6 oz cups", "qty": "45"}, {"item": "Bananas", "qty": "25 lb"}]', '["Whisk the cereal into boiling water; cook 3 minutes, stirring, until smooth.", "Slice the bananas at packing so they do not brown."]', '["adult_day_care", "breakfast", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Crema de trigo y yogur', 'Es el único día sin grano integral en el desayuno; ese día el integral viene en el almuerzo.', '[{"item": "Crema de trigo enriquecida", "qty": "4 lb"}, {"item": "Agua", "qty": "3 galones"}, {"item": "Yogur de 6 oz", "qty": "45"}, {"item": "Plátanos", "qty": "25 lb"}]', '["Bata el cereal en agua hirviendo; cocine 3 minutos sin dejar de mover hasta que quede liso.", "Rebane el plátano al empacar para que no se ponga oscuro."]', 'Cream of wheat 1 cup · low-fat yogurt 6 oz · banana ½ cup · milk 1 cup', 'Crema de trigo 1 taza · yogur bajo en grasa 6 oz · plátano ½ taza · leche 1 taza', 'cream_of_wheat_and_yogurt');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_whole_grain_cereal_and_yogurt', 'Whole-grain cereal and yogurt', 'The easiest breakfast on the cycle. Use it on a heavy lunch prep day.', '[{"item": "Whole-grain cereal, low sugar", "qty": "45 single-serve bowls or 5 lb bulk"}, {"item": "Low-fat yogurt, 6 oz", "qty": "45"}, {"item": "Strawberries", "qty": "9 lb"}]', '["No cooking. Cereal stays sealed and dry; milk goes separately so nothing is soggy on arrival.", "Cereal must be 6 g added sugar or less per dry ounce."]', '["adult_day_care", "breakfast", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Cereal integral y yogur', 'Es el desayuno más fácil del ciclo. Úselo en un día de mucha preparación de almuerzo.', '[{"item": "Cereal integral bajo en azúcar", "qty": "45 porciones"}, {"item": "Yogur de 6 oz", "qty": "45"}, {"item": "Fresas", "qty": "9 lb"}]', '["No se cocina. El cereal va sellado y seco; la leche va aparte para que no llegue aguado.", "El cereal debe tener 6 g de azúcar añadida o menos por onza seca."]', 'Fortified whole-grain cereal 1 cup WG · low-fat yogurt 6 oz · strawberries ½ cup · milk 1 cup', 'Cereal integral fortificado 1 taza WG · yogur 6 oz · fresa ½ taza · leche 1 taza', 'whole_grain_cereal_and_yogurt');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_whole_grain_cereal_and_cottage_cheese', 'Whole-grain cereal and cottage cheese', 'Cold pack only. Keep below 41°F until handoff.', '[{"item": "Whole-grain cereal, low sugar", "qty": "45 servings"}, {"item": "Low-fat cottage cheese", "qty": "14 lb"}, {"item": "Diced pears in juice", "qty": "3 #10 cans"}]', '["No cooking. Portion the cottage cheese and drained pears cold."]', '["adult_day_care", "breakfast", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Cereal integral y requesón', 'Solo bolsa fría. Manténgalo por debajo de 41°F hasta la entrega.', '[{"item": "Cereal integral bajo en azúcar", "qty": "45 porciones"}, {"item": "Requesón bajo en grasa", "qty": "14 lb"}, {"item": "Pera en jugo", "qty": "3 latas #10"}]', '["No se cocina. Sirva el requesón y la pera escurrida en frío."]', 'Fortified whole-grain cereal 1 cup WG · cottage cheese ½ cup · pear ½ cup · milk 1 cup', 'Cereal integral fortificado 1 taza WG · requesón ½ taza · pera ½ taza · leche 1 taza', 'whole_grain_cereal_and_cottage_cheese');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_cuban_toast_and_yogurt', 'Cuban toast and yogurt', 'Toast lightly; hard crusts are a chewing problem.', '[{"item": "Cuban bread", "qty": "8 loaves"}, {"item": "Butter or oil spread", "qty": "1 lb"}, {"item": "Low-fat yogurt, 6 oz", "qty": "45"}, {"item": "Orange sections", "qty": "9 lb"}]', '["Split and lightly butter the bread, toast until just golden, not hard.", "Cut into 2 oz portions. Bread for older adults should be soft inside."]', '["adult_day_care", "breakfast", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Tostada cubana y yogur', 'Tueste poco; la corteza dura es un problema para masticar.', '[{"item": "Pan cubano", "qty": "8 flautas"}, {"item": "Mantequilla o untable", "qty": "1 lb"}, {"item": "Yogur de 6 oz", "qty": "45"}, {"item": "Gajos de naranja", "qty": "9 lb"}]', '["Abra el pan, unte ligeramente y tueste apenas hasta dorar; no debe quedar duro.", "Corte porciones de 2 oz. El pan para adultos mayores debe quedar suave por dentro."]', 'Cuban bread, toasted, 2 oz eq · low-fat yogurt 6 oz · orange sections ½ cup · milk 1 cup', 'Pan cubano tostado 2 oz eq · yogur 6 oz · gajos de naranja ½ taza · leche 1 taza', 'cuban_toast_and_yogurt');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_cuban_toast_and_cottage_cheese', 'Cuban toast and cottage cheese', 'Pack the toast separate from the wet items so it does not go soft.', '[{"item": "Cuban bread", "qty": "8 loaves"}, {"item": "Low-fat cottage cheese", "qty": "14 lb"}, {"item": "Mixed fruit in juice", "qty": "3 #10 cans"}]', '["Toast as above. Portion the cottage cheese and drained fruit cold."]', '["adult_day_care", "breakfast", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Tostada cubana y requesón', 'Empaque la tostada separada de lo húmedo para que no se ablande.', '[{"item": "Pan cubano", "qty": "8 flautas"}, {"item": "Requesón bajo en grasa", "qty": "14 lb"}, {"item": "Frutas mixtas en jugo", "qty": "3 latas #10"}]', '["Tueste como arriba. Sirva el requesón y la fruta escurrida en frío."]', 'Cuban bread, toasted, 2 oz eq · cottage cheese ½ cup · mixed fruit ½ cup · milk 1 cup', 'Pan cubano tostado 2 oz eq · requesón ½ taza · frutas mixtas ½ taza · leche 1 taza', 'cuban_toast_and_cottage_cheese');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_egg_and_cheese_bocadito', 'Egg and cheese bocadito', 'This is the no-pork version of the ham bocadito.', '[{"item": "Cuban bread", "qty": "8 loaves"}, {"item": "Eggs", "qty": "4 dozen"}, {"item": "American or Swiss cheese slices", "qty": "45"}, {"item": "Bananas", "qty": "25 lb"}]', '["Cook the eggs flat in sheet pans at 325°F, about 12 minutes, then cut into portions.", "Assemble bread, egg, cheese. Cook eggs to 160°F.", "Wrap warm so the sandwich steams slightly and stays soft."]', '["adult_day_care", "breakfast", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Bocadito de huevo y queso', 'Esta es la versión sin cerdo del bocadito de jamón.', '[{"item": "Pan cubano", "qty": "8 flautas"}, {"item": "Huevos", "qty": "4 docenas"}, {"item": "Queso americano o suizo en lascas", "qty": "45"}, {"item": "Plátanos", "qty": "25 lb"}]', '["Cuaje los huevos en bandeja a 325°F, unos 12 minutos, y corte en porciones.", "Arme pan, huevo y queso. Huevos a 160°F.", "Envuelva tibio para que el bocadito se mantenga suave."]', 'Egg and cheese on Cuban bread 2 oz eq · egg 1 and cheese 1 oz · banana ½ cup · milk 1 cup', 'Huevo y queso en pan cubano 2 oz eq · huevo 1 y queso 1 oz · plátano ½ taza · leche 1 taza', 'egg_and_cheese_bocadito');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_egg_and_ham_bocadito', 'Egg and ham bocadito', 'Ham is the only cured meat on the cycle, at 1 oz, for sodium. Omit for the no-pork version.', '[{"item": "Cuban bread", "qty": "8 loaves"}, {"item": "Eggs", "qty": "4 dozen"}, {"item": "Lean deli ham, low sodium", "qty": "3 lb"}, {"item": "Orange sections", "qty": "9 lb"}]', '["Cook the eggs as above. Warm the ham briefly; do not crisp it.", "Assemble and wrap warm. Eggs to 160°F."]', '["adult_day_care", "breakfast", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Bocadito de huevo y jamón', 'El jamón es la única carne curada del ciclo, de 1 oz, por el sodio. Se omite en la versión sin cerdo.', '[{"item": "Pan cubano", "qty": "8 flautas"}, {"item": "Huevos", "qty": "4 docenas"}, {"item": "Jamón magro bajo en sodio", "qty": "3 lb"}, {"item": "Gajos de naranja", "qty": "9 lb"}]', '["Cuaje los huevos como arriba. Caliente el jamón apenas; no lo tueste.", "Arme y envuelva tibio. Huevos a 160°F."]', 'Egg and lean ham on Cuban bread 2 oz eq · egg 1, ham 1 oz · orange sections ½ cup · milk 1 cup', 'Huevo y jamón magro en pan cubano 2 oz eq · huevo 1, jamón 1 oz · gajos de naranja ½ taza · leche', 'egg_and_ham_bocadito');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_scrambled_eggs_with_peppers', 'Scrambled eggs with peppers', 'Cook the vegetables first and longer than you would for a restaurant plate.', '[{"item": "Eggs", "qty": "4 dozen"}, {"item": "Bell pepper, small dice", "qty": "3 lb"}, {"item": "Onion, small dice", "qty": "2 lb"}, {"item": "Whole-wheat bread", "qty": "6 loaves"}, {"item": "Oil", "qty": "1 cup"}]', '["Sweat the peppers and onions until fully soft, 8 minutes. Crunchy pepper is a chewing problem.", "Add the beaten eggs; scramble soft to 160°F.", "Toast the bread lightly."]', '["adult_day_care", "breakfast", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Huevos revueltos con ají', 'Cocine los vegetales primero y por más tiempo de lo que haría en un restaurante.', '[{"item": "Huevos", "qty": "4 docenas"}, {"item": "Ají en cubitos", "qty": "3 lb"}, {"item": "Cebolla en cubitos", "qty": "2 lb"}, {"item": "Pan integral", "qty": "6 barras"}, {"item": "Aceite", "qty": "1 taza"}]', '["Sude el ají y la cebolla hasta que estén completamente blandos, 8 minutos. El ají crujiente es difícil de masticar.", "Agregue los huevos batidos; revuelva suave hasta 160°F.", "Tueste el pan ligeramente."]', 'Scrambled eggs with soft peppers and onion 1 egg · whole-wheat toast 2 slices WG · orange sections ½ cup · milk', 'Huevos revueltos con ají y cebolla blanditos 1 huevo · pan integral tostado 2 rebanadas WG · gajos de naranja ½ taza · leche', 'scrambled_eggs_with_peppers');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_spanish_omelet', 'Spanish omelet', 'Bakes in sheet pans, which is the only way this scales.', '[{"item": "Eggs", "qty": "4 dozen"}, {"item": "Potato, thin sliced", "qty": "8 lb"}, {"item": "Onion, sliced", "qty": "3 lb"}, {"item": "Olive oil", "qty": "2 cups"}, {"item": "Cuban bread", "qty": "8 loaves"}]', '["Cook the potato and onion slowly in oil until completely soft, 20 minutes. Do not brown.", "Mix with beaten egg, pour into sheet pans, bake at 325°F for 20 to 25 minutes to 160°F.", "Cut into portions once set."]', '["adult_day_care", "breakfast", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Tortilla española', 'Se hornea en bandeja, que es la única forma de hacerla en volumen.', '[{"item": "Huevos", "qty": "4 docenas"}, {"item": "Papa en rodajas finas", "qty": "8 lb"}, {"item": "Cebolla en rodajas", "qty": "3 lb"}, {"item": "Aceite de oliva", "qty": "2 tazas"}, {"item": "Pan cubano", "qty": "8 flautas"}]', '["Cocine la papa y la cebolla despacio en aceite hasta que estén completamente blandas, 20 minutos. No las dore.", "Mezcle con el huevo batido, vierta en bandejas y hornee a 325°F de 20 a 25 minutos hasta 160°F.", "Corte en porciones cuando cuaje."]', 'Spanish omelet with potato and onion 1 egg · Cuban bread 2 oz eq · pear ½ cup · milk 1 cup', 'Tortilla de papa y cebolla 1 huevo · pan cubano 2 oz eq · pera ½ taza · leche 1 taza', 'spanish_omelet');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_whole_grain_french_toast', 'Whole-grain French toast', 'Baking beats the griddle at this volume and holds better in transport.', '[{"item": "Whole-wheat bread", "qty": "6 loaves"}, {"item": "Eggs", "qty": "4 dozen"}, {"item": "Milk", "qty": "1 gal"}, {"item": "Cinnamon", "qty": "3 tbsp"}, {"item": "Vanilla", "qty": "¼ cup"}, {"item": "Sliced peaches in juice", "qty": "3 #10 cans"}]', '["Whisk eggs, milk, cinnamon and vanilla. Dip the bread; do not soak it to mush.", "Bake on oiled sheet pans at 375°F for 15 minutes, turning once, to 160°F.", "No syrup is served; the fruit is the sweetness."]', '["adult_day_care", "breakfast", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Torrejas integrales (French toast)', 'Hornear es mejor que la plancha en este volumen y aguanta mejor el transporte.', '[{"item": "Pan integral", "qty": "6 barras"}, {"item": "Huevos", "qty": "4 docenas"}, {"item": "Leche", "qty": "1 galón"}, {"item": "Canela", "qty": "3 cdas"}, {"item": "Vainilla", "qty": "¼ taza"}, {"item": "Melocotón en jugo", "qty": "3 latas #10"}]', '["Bata huevos, leche, canela y vainilla. Pase el pan; no lo deje empapar hasta deshacerse.", "Hornee en bandejas aceitadas a 375°F por 15 minutos, volteando una vez, hasta 160°F.", "No se sirve sirope; la fruta es el dulzor."]', 'Whole-wheat French toast 2 slices WG · egg in the batter · peaches ½ cup · milk 1 cup', 'Torrejas de pan integral 2 rebanadas WG · huevo en la mezcla · melocotón ½ taza · leche 1 taza', 'whole_grain_french_toast');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, program_key) VALUES ('rcp_adc_whole_grain_pancakes', 'Whole-grain pancakes', 'Stack with parchment between layers so they do not weld together.', '[{"item": "Whole-grain pancake mix", "qty": "10 lb"}, {"item": "Water or milk", "qty": "per mix"}, {"item": "Low-fat yogurt, 6 oz", "qty": "45"}, {"item": "Strawberries, sliced", "qty": "9 lb"}]', '["Bake on sheet pans at 400°F for 10 to 12 minutes, or griddle in batches.", "Serve with fruit, not syrup."]', '["adult_day_care", "breakfast", "boca_raton_adc"]', 'published', 1790000000000, 1790000000000, 'Panqueques integrales', 'Apile con papel entre capas para que no se peguen.', '[{"item": "Mezcla para panqueques integrales", "qty": "10 lb"}, {"item": "Agua o leche", "qty": "según la mezcla"}, {"item": "Yogur de 6 oz", "qty": "45"}, {"item": "Fresas en rodajas", "qty": "9 lb"}]', '["Hornee en bandeja a 400°F de 10 a 12 minutos, o haga por tandas en la plancha.", "Sirva con fruta, no con sirope."]', 'Whole-grain pancakes 2 · yogurt 6 oz · strawberries ½ cup · milk 1 cup', 'Panqueques integrales 2 · yogur 6 oz · fresa ½ taza · leche 1 taza', 'whole_grain_pancakes');

-- ---------------------------------------------------------------- the 4-week cycle
INSERT OR IGNORE INTO program_cycles (id, name, weeks, active, notes, created_at, updated_at) VALUES ('pcyc_adc4', 'Adult day care — 4-week cycle (Exhibit A)', 4, 1, 'Breakfast, lunch and afternoon snack, Monday to Friday, for adults 80+. Planned to Rule 59A-16.105 and the USDA adult meal pattern. Not servable until the dietitian fields on this row are filled in.', 1790000000000, 1790000000000);
